const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper for async evaluation
  const getInfo = (obj) =>
    new Promise((resolve, reject) => obj.evaluate(resolve, reject));

  try {
    // 1. Geometry & Time Definitions
    // Wuhan approximate bounding box
    const wuhan = ee.Geometry.Rectangle([113.8, 30.3, 114.7, 30.9]);
    const scale = 10000; // 10 km, suitable for S5P (~7 km native)
    const period1 = { start: '2020-01-01', end: '2020-01-21' }; // Jan 1–20 inclusive
    const period2 = { start: '2020-02-10', end: '2020-02-26' }; // Feb 10–25 inclusive

    // 2. Data Acquisition & Masking
    const offlId = 'COPERNICUS/S5P/OFFL/L3_NO2';
    const nrtiId = 'COPERNICUS/S5P/NRTI/L3_NO2';

    function maskNO2(img) {
      const qa = img.select('qa_value');
      const cf = img.select('cloud_fraction');
      const mask = qa.gte(0.75).and(cf.lte(0.3));
      return img.updateMask(mask);
    }

    function getCol(id, start, end, geom) {
      return ee.ImageCollection(id)
        .filterDate(start, end)
        .filterBounds(geom)
        .map(maskNO2);
    }

    async function getBestCollection(start, end, geom) {
      let col = getCol(offlId, start, end, geom);
      let n = await getInfo(col.size());
      if (!n || n === 0) {
        col = getCol(nrtiId, start, end, geom);
        n = await getInfo(col.size());
        if (!n || n === 0) {
          return { col: null, id: null, n: 0 };
        }
        return { col, id: nrtiId, n };
      }
      return { col, id: offlId, n };
    }

    async function statsFor(col, geom) {
      const band = 'tropospheric_NO2_column_number_density';
      const nImages = await getInfo(col.size());

      const countImg = col.select(band).reduce(ee.Reducer.count());
      const validMask = countImg.gt(0).selfMask().rename('valid');
      const validPix = await getInfo(
        validMask.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geom,
          scale: scale,
          maxPixels: 1e9,
        }).get('valid')
      );
      const validPixels = validPix || 0;

      // If no valid pixels, short-circuit
      if (validPixels === 0) {
        return { nImages, validPixels, meanNO2: null, meanCloud: null };
      }

      const meanNO2 = await getInfo(
        col
          .select(band)
          .mean()
          .reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: geom,
            scale: scale,
            maxPixels: 1e9,
          })
          .get(band)
      );

      const meanCloud = await getInfo(
        col
          .select('cloud_fraction')
          .mean()
          .reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: geom,
            scale: scale,
            maxPixels: 1e9,
          })
          .get('cloud_fraction')
      );

      return { nImages, validPixels, meanNO2, meanCloud };
    }

    // Build collections
    const best1 = await getBestCollection(period1.start, period1.end, wuhan);
    const best2 = await getBestCollection(period2.start, period2.end, wuhan);

    if (!best1.col || !best2.col) {
      console.log('Dataset: S5P NO2 (OFFL, fallback NRTI if needed)');
      console.log('QA/Cloud mask: qa_value ≥ 0.75, cloud_fraction ≤ 0.3');
      console.log(`P1 Images: ${best1.n || 0}`);
      console.log(`P2 Images: ${best2.n || 0}`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1');
      return;
    }

    const s1 = await statsFor(best1.col, wuhan);
    const s2 = await statsFor(best2.col, wuhan);

    // Check C2: No valid pixels after masking
    if ((s1.validPixels || 0) === 0 || (s2.validPixels || 0) === 0) {
      console.log('Dataset: ' + (best1.id === best2.id ? best1.id : `${best1.id} & ${best2.id}`));
      console.log('QA/Cloud mask: qa_value ≥ 0.75, cloud_fraction ≤ 0.3');
      console.log(`P1 Images: ${s1.nImages} | Valid spatial pixels: ${s1.validPixels || 0}`);
      console.log(`P2 Images: ${s2.nImages} | Valid spatial pixels: ${s2.validPixels || 0}`);
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      console.log('C2');
      return;
    }

    // 3. Validation for calculation failure (C3)
    function invalidNO2(v) {
      if (v === null || v === undefined) return true;
      if (!isFinite(v)) return true;
      if (v < 0 || v > 0.01) return true; // outside plausible tropospheric NO2 range
      return false;
    }

    if (invalidNO2(s1.meanNO2) || invalidNO2(s2.meanNO2)) {
      console.log('Dataset: ' + (best1.id === best2.id ? best1.id : `${best1.id} & ${best2.id}`));
      console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
      console.log('C3');
      return;
    }

    // 4. Calculation and Decision
    const p1 = s1.meanNO2;
    const p2 = s2.meanNO2;
    const change = p2 - p1;
    const pct = (change / p1) * 100;

    // 5. Output concise evidence (≤20 lines)
    console.log('Dataset: ' + (best1.id === best2.id ? best1.id : `${best1.id} & ${best2.id}`));
    console.log('Region: Wuhan bbox [113.8,30.3,114.7,30.9]');
    console.log('QA/Cloud mask: qa_value ≥ 0.75, cloud_fraction ≤ 0.3');
    console.log(`P1 (2020-01-01 to 2020-01-20): Images=${s1.nImages}, ValidPix=${s1.validPixels}, Mean NO2=${p1.toExponential(2)} mol/m^2, Mean Cloud=${( (s1.meanCloud||0)*100 ).toFixed(1)}%`);
    console.log(`P2 (2020-02-10 to 2020-02-25): Images=${s2.nImages}, ValidPix=${s2.validPixels}, Mean NO2=${p2.toExponential(2)} mol/m^2, Mean Cloud=${( (s2.meanCloud||0)*100 ).toFixed(1)}%`);
    console.log(`Change: Δ=${change.toExponential(2)} mol/m^2 (${pct.toFixed(1)}%)`);

    // Final tag
    if (p2 < p1) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log('D: Error occurred - ' + (err && err.message ? err.message : String(err)));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
